@-moz-document domain("roblox.com") {

/* CREEPER MODE */
html, body {
    background: #071b0b !important;
    color: #baffbd !important;
}

/* Navigation */
nav, header {
    background: #10351a !important;
}

/* Main Roblox panels */
.game-home-page-container,
.content {
    background-color: #0b2511 !important;
}

/* Game cards */
.game-card,
.game-card-container {
    border: 2px solid #268b37 !important;
    border-radius: 12px !important;
}

/* Buttons */
button {
    background-color: #31b94a !important;
    color: #061508 !important;
}

/* Green links */
a {
    color: #65ef79 !important;
}

}

